package com.muthumol.player.dummy;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;import java.nio.*;import java.util.*;import androidx.media3.common.C;import androidx.media3.common.audio.AudioProcessor.AudioFormat;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class TvUpgradeTest {
 @Test public void dialogueProcessorLimitsFirstTransientAndEveryChannelWithoutWrapping()throws Exception {for(int mode:new int[]{1,2,3})for(int channels:new int[]{1,2,3,4,5,6,7,8}){TvAudioProcessor p=new TvAudioProcessor();p.mode=mode;p.percent=300;p.configure(new AudioFormat(48000,channels,C.ENCODING_PCM_16BIT));p.flush();ByteBuffer in=ByteBuffer.allocateDirect(3000*channels*2).order(ByteOrder.nativeOrder());for(int i=0;i<3000*channels;i++)in.putShort((short)(i%2==0?32767:-32768));in.flip();p.queueInput(in);ByteBuffer out=p.getOutput().order(ByteOrder.nativeOrder());assertFalse(in.hasRemaining());assertEquals(3000*Math.min(2,channels)*2,out.remaining());while(out.hasRemaining())assertTrue(Math.abs((int)out.getShort())<=32440);}}
 @Test public void corruptFloatAudioAndEmptyDrainsDoNotProduceFullScaleNoise()throws Exception {TvAudioProcessor p=new TvAudioProcessor();p.configure(new AudioFormat(48000,2,C.ENCODING_PCM_FLOAT));p.flush();p.queueInput(androidx.media3.common.audio.AudioProcessor.EMPTY_BUFFER);ByteBuffer in=ByteBuffer.allocateDirect(16).order(ByteOrder.nativeOrder());in.putFloat(Float.NaN).putFloat(Float.POSITIVE_INFINITY).putFloat(0).putFloat(0).flip();p.queueInput(in);ByteBuffer out=p.getOutput().order(ByteOrder.nativeOrder());while(out.hasRemaining())assertEquals(0,out.getShort());}
 @Test public void silenceStaysSilentAndMultichannelCanBePreserved()throws Exception {TvAudioProcessor p=new TvAudioProcessor();p.fold=false;p.configure(new AudioFormat(44100,6,C.ENCODING_PCM_16BIT));p.flush();ByteBuffer in=ByteBuffer.allocateDirect(1200).order(ByteOrder.nativeOrder());p.queueInput(in);ByteBuffer out=p.getOutput();assertEquals(1200,out.remaining());while(out.hasRemaining())assertEquals(0,out.get());}
 @Test public void episodesAreSortedAcrossSeasonsAndNeverCrossSeries(){Movie a=movie("Show.S01E02.mkv","a"),b=movie("Show.S02E01.mkv","b"),c=movie("Show.S01E01.mkv","c"),d=movie("Other.S01E03.mkv","d");List<Movie> all=Arrays.asList(b,d,a,c);assertSame(a,TvLibrary.neighbour(all,c,1));assertSame(b,TvLibrary.neighbour(all,a,1));assertNull(TvLibrary.neighbour(all,b,1));assertNull(TvLibrary.neighbour(all,c,-1));}
 @Test public void savedCollectionsAndSearchSurviveNewLibraryInstance(){android.content.Context c=RuntimeEnvironment.getApplication();c.getSharedPreferences("tv-library",0).edit().clear().commit();TvLibrary l=new TvLibrary(c);Movie m=movie("The Movie 2025.mkv","saved");l.toggle(m,"later");List<Movie> found=new TvLibrary(c).list(c,Collections.emptyList(),"Watch later","movie 2025",0);assertEquals(1,found.size());assertEquals("saved",found.get(0).identity);assertTrue(TvLibrary.matches("Film.2025.1080p.mkv","2025 film"));assertFalse(TvLibrary.matches("Film.2025.mkv","different"));}
 @Test public void timeInputRejectsNegativeAndOverflow(){assertEquals(3723000,TvPlayerTools.parseTime("1:02:03"));for(String bad:new String[]{"-1:20","9999999999999999999999","1:2:3:4","oops"})try{TvPlayerTools.parseTime(bad);fail(bad);}catch(RuntimeException expected){}}
 @Test public void backupExcludesCredentialsAndSubtitleDevicePaths(){assertFalse(TvBackup.allowed("apiKey"));assertFalse(TvBackup.allowed("token"));assertFalse(TvBackup.allowed("externalSubtitleUri:movie"));assertTrue(TvBackup.allowed("pos:movie"));assertTrue(TvBackup.allowed("tvAudioMode"));}
 @Test public void backupRoundTripPreservesLongAndFloatPreferenceTypes()throws Exception {android.content.SharedPreferences prefs=RuntimeEnvironment.getApplication().getSharedPreferences("tv-backup-test",0);android.content.SharedPreferences.Editor edit=prefs.edit();TvBackup.restoreValue(edit,"pos:a",new org.json.JSONObject(TvBackup.encode(1200L).toString()));TvBackup.restoreValue(edit,"tvSpeed",new org.json.JSONObject(TvBackup.encode(1.25f).toString()));edit.commit();assertEquals(1200L,prefs.getLong("pos:a",0));assertEquals(1.25f,prefs.getFloat("tvSpeed",0),.001);TvBackup.restoreValue(prefs.edit(),"pos:a",new org.json.JSONObject().put("type","boolean").put("value",true));assertEquals(1200L,prefs.getLong("pos:a",0));}
 @Test public void offlineProviderOnlyExposesNamedVideoFilesReadOnly()throws Exception {android.content.Context c=RuntimeEnvironment.getApplication();java.io.File dir=new java.io.File(c.getFilesDir(),"offline-videos");dir.mkdirs();String id=MediaCache.key("offline-test");java.io.File file=new java.io.File(dir,id+".video");try(java.io.FileOutputStream o=new java.io.FileOutputStream(file)){o.write(new byte[]{1,2,3});}OfflineProvider provider=Robolectric.buildContentProvider(OfflineProvider.class).create().get();android.net.Uri uri=android.net.Uri.parse("content://com.muthumol.player.dummy.offline/"+id+".video");try(android.os.ParcelFileDescriptor fd=provider.openFile(uri,"r")){assertEquals(3,fd.getStatSize());}assertThrows(java.io.FileNotFoundException.class,()->provider.openFile(uri,"w"));assertThrows(java.io.FileNotFoundException.class,()->provider.openFile(android.net.Uri.parse("content://com.muthumol.player.dummy.offline/../shared_prefs/player.xml"),"r"));file.delete();}
 Movie movie(String title,String key){Movie m=new Movie();m.title=title;m.identity=key;return m;}
}
